from scapy.all import *
from urllib.parse import unquote_plus, parse_qs
from collections import Counter
import base64

def analyze_field(data):
    """Analyze a field for patterns and possible encodings"""
    analysis = {
        'length': len(data),
        'char_dist': dict(Counter(data)),
        'possible_encoding': []
    }

    # Check for possible encodings
    try:
        decoded = base64.b64decode(data)
        analysis['possible_encoding'].append('base64')
    except:
        pass

    # Check if hex encoded
    if all(c in '0123456789abcdefABCDEF' for c in data):
        analysis['possible_encoding'].append('hex')

    return analysis

def extract_form_data():
    packets = rdpcap('/home/ctfplayer/ctf_files/cap.pcap')
    form_submissions = []

    for packet in packets:
        if packet.haslayer(TCP) and packet.haslayer(Raw):
            # Check if it's a POST request to 192.168.0.21:8080
            if packet[IP].dst == "192.168.0.21" and packet[TCP].dport == 8080:
                raw_data = packet[Raw].load.decode('utf-8', errors='ignore')
                if raw_data.startswith('POST'):
                    # Extract form data
                    try:
                        body = raw_data.split('\r\n\r\n')[1]
                        parsed = parse_qs(body)

                        # URL decode all fields
                        decoded_form = {}
                        for field in ['name', 'lname', 'school', 'major', 'c', 's', 'text', 'n', 'x']:
                            if field in parsed:
                                decoded_form[field] = unquote_plus(parsed[field][0])

                        form_submissions.append(decoded_form)
                    except:
                        continue

    return form_submissions

def main():
    print("Analyzing PCAP file...\n")

    submissions = extract_form_data()

    print(f"Found {len(submissions)} form submissions\n")
    print("Form Submissions:")
    for i, sub in enumerate(submissions, 1):
        print(f"\nSubmission {i}:")
        for field, value in sub.items():
            print(f"{field}: {value}")

    print("\nDetailed Analysis of 'n' and 'x' fields:")
    n_values = [sub.get('n', '') for sub in submissions if 'n' in sub]
    x_values = [sub.get('x', '') for sub in submissions if 'x' in sub]

    print("\n'n' field analysis:")
    for i, n in enumerate(n_values):
        print(f"\nEntry {i+1}:")
        analysis = analyze_field(n)
        print(f"Length: {analysis['length']}")
        print(f"Character distribution: {analysis['char_dist']}")
        print(f"Possible encodings: {analysis['possible_encoding']}")

    print("\n'x' field analysis:")
    for i, x in enumerate(x_values):
        print(f"\nEntry {i+1}:")
        analysis = analyze_field(x)
        print(f"Length: {analysis['length']}")
        print(f"Character distribution: {analysis['char_dist']}")
        print(f"Possible encodings: {analysis['possible_encoding']}")

if __name__ == "__main__":
    main()

