import re

def extract_form_data(pcap_file):
    packets = rdpcap(pcap_file)
    data = []

    for packet in packets:
        if Raw in packet:
            raw_data = packet[Raw].load
            try:
                decoded = raw_data.decode('utf-8', errors='ignore')
                if 'x=' in decoded:
                    # Extract x value using regex to handle various formats
                    match = re.search(r'x=([0-9a-fA-F]+)', decoded)
                    if match:
                        hex_value = match.group(1)
                        if len(hex_value) % 2 == 0:  # Ensure even length
                            data.append(hex_value)
            except:
                pass

    return data

def hex_to_bytes(hex_data):
    # Convert hex string to bytes
    try:
        return bytes.fromhex(hex_data)
    except:
        return None

def try_reconstruct_image(data, filename_prefix="output"):
    data_len = len(data)
    print(f"Trying to reconstruct image from {data_len} bytes")

    # Try as direct image bytes
    try:
        with open(f"{filename_prefix}_raw.png", 'wb') as f:
            f.write(data)
    except:
        pass

    # Calculate possible dimensions
    for width in range(10, 1000):
        if data_len % width == 0:
            height = data_len // width

            if height > 0 and height < 1000:  # Reasonable height limits
                # Try grayscale
                try:
                    img = Image.frombytes('L', (width, height), data)
                    img.save(f"{filename_prefix}_{width}x{height}_gray.png")
                    print(f"Saved {width}x{height} grayscale image")
                except:
                    pass

                # Try RGB if we have enough data
                if data_len >= (width * height * 3):
                    try:
                        img = Image.frombytes('RGB', (width, height), data[:width*height*3])
                        img.save(f"{filename_prefix}_{width}x{height}_rgb.png")
                        print(f"Saved {width}x{height} RGB image")
                    except:
                        pass

