    submissions = []

    for packet in packets:
        if Raw in packet:
            raw_data = packet[Raw].load.decode('utf-8', errors='ignore')
            if 'x=' in raw_data:
                parts = raw_data.split('&')
                for part in parts:
                    if part.startswith('x='):
                        x_value = part.split('=')[1]
                        if len(x_value) > 0:
                            submissions.append(x_value)

    return submissions

def try_reconstruct_image(binary_data):
    # Try different image sizes
    widths = [100, 120, 150, 200, 250, 300]
    heights = [100, 120, 150, 200, 250, 300]

    for width in widths:
        for height in heights:
            try:
                # Try as RGB image
                data_array = np.frombuffer(binary_data, dtype=np.uint8)
                if len(data_array) >= width * height * 3:
                    img_array = data_array[:width * height * 3].reshape((height, width, 3))
                    img = Image.fromarray(img_array)
                    img.save(f'rgb_{width}x{height}.png')
                    print(f"Saved RGB image {width}x{height}")
            except Exception as e:
                pass

            try:
                # Try as grayscale
                if len(binary_data) >= width * height:
                    img_array = data_array[:width * height].reshape((height, width))
                    img = Image.fromarray(img_array, 'L')
                    img.save(f'gray_{width}x{height}.png')
                    print(f"Saved grayscale image {width}x{height}")
            except Exception as e:
                pass

def main():
    pcap_file = '/home/ctfplayer/ctf_files/cap.pcap'

    # Extract hex values
    hex_values = extract_form_data(pcap_file)
    print(f"Found {len(hex_values)} form submissions")

    # Convert hex to binary
