    for hex_val in hex_values:
        try:
            all_binary += binascii.unhexlify(hex_val)
        except:
            continue

    print(f"Total binary size: {len(all_binary)} bytes")

    # Save raw binary
    with open('all_binary.bin', 'wb') as f:
        f.write(all_binary)

    # Try to reconstruct images
    try_reconstruct_image(all_binary)

    # Also try with PNG header
    png_header = b'\x89PNG\r\n\x1a\n'
