        width, height = img.size
        print(f"\nChecking {filename} ({width}x{height})")

        # Convert to RGB if necessary
        if img.mode != 'RGB':
            img = img.convert('RGB')

        # Check for text-like patterns (high contrast areas)
        pixels = img.load()
        text_like = False
        for y in range(height):
            row = ''
            for x in range(width):
                r, g, b = pixels[x, y]
                avg = (r + g + b) // 3
                if avg < 128:
                    row += '#'
                else:
                    row += ' '
            if '#' in row and ' ' in row:  # Line has both black and white pixels
                text_like = True
                print(row)

        if not text_like:
            print("No text-like patterns found")

    except Exception as e:
        print(f"Error processing {filename}: {str(e)}")

