def try_decode(data):
    results = []
    # Try base64
    try:
        b64_decoded = base64.b64decode(data + "=" * (-len(data) % 4))
        results.append(("base64", b64_decoded))
    except:
        pass

    # Try hex
    try:
        hex_decoded = binascii.unhexlify(data)
        results.append(("hex", hex_decoded))
    except:
        pass

    # Try URL decode
    try:
        url_decoded = urllib.parse.unquote(data)
        if url_decoded != data:
            results.append(("url", url_decoded))
    except:
        pass

    return results

def process_packet(packet):
    if packet.haslayer('Raw'):
        try:
            # Extract POST data
            raw_load = packet[Raw].load.decode('utf-8')
            if 'n=' in raw_load:
                # Parse POST parameters
                params = parse_qs(raw_load)
                if 'n' in params:
                    n_value = params['n'][0]
                    print(f"\nFound n value: {n_value}")

                    # Try different decodings
                    decoded = try_decode(n_value)
                    for decode_type, result in decoded:
                        try:
                            print(f"{decode_type} decoded: {result}")
                            # Check for flag format
                            if b'FLAG{' in result or 'FLAG{' in str(result):
                                print("POTENTIAL FLAG FOUND!")
                        except:
                            print(f"{decode_type} decoded (binary): {result}")

                    # Check if 'x' field is present
                    if 'x' in params:
                        print(f"Associated x value: {params['x'][0]}")
        except:
            pass

