def decode_hex(hex_str):
    try:
        # Remove any whitespace and make sure length is even
        hex_str = ''.join(hex_str.split())
        if len(hex_str) % 2 != 0:
            hex_str = hex_str[:-1]
        return binascii.unhexlify(hex_str)
    except:
        return None

def extract_fields(raw_data):
    fields = {}
    matches = re.findall(r'([^&=]+)=([^&\n]+)', raw_data)
    for key, value in matches:
        fields[key] = unquote_plus(value)
    return fields

